CREATE PROCEDURE CLAIMS.SETTLE_AND_DISBURSE (
    IN  P_BATCH_ID          BIGINT,
    IN  P_TENANT_ID         CHAR(8),
    IN  P_CUTOFF_DATE       DATE,
    OUT P_SETTLED_COUNT     INTEGER,
    OUT P_DISBURSED_TOTAL   DECIMAL(15,2),
    OUT P_STATUS            VARCHAR(30)
)
LANGUAGE SQL
MODIFIES SQL DATA
DYNAMIC RESULT SETS 1
SQL SECURITY DEFINER
P_SETTLE: BEGIN
    DECLARE V_NOW               TIMESTAMP DEFAULT CURRENT TIMESTAMP;
    DECLARE V_ROWS              INTEGER   DEFAULT 0;
    DECLARE V_CLAIM_ID          BIGINT;
    DECLARE V_AMOUNT            DECIMAL(15,2);
    DECLARE V_RESERVE           DECIMAL(15,2);
    DECLARE V_NET               CLAIMS.MONEY;
    DECLARE V_HOLD_TOTAL        DECIMAL(15,2);
    DECLARE V_STALE_TOTAL       DECIMAL(15,2);
    DECLARE V_PAYEE_ID          BIGINT;
    DECLARE V_QUEUE_ID          BIGINT;
    DECLARE V_DISB_ID           BIGINT;
    DECLARE V_PRIOR_AMOUNT      DECIMAL(15,2);
    DECLARE V_DONE              SMALLINT  DEFAULT 0;
    DECLARE V_MODE              VARCHAR(20);
    DECLARE V_REJECTED          INTEGER   DEFAULT 0;

    DECLARE BATCH_LOCKED CONDITION FOR SQLSTATE '75001';

    DECLARE C_SETTLE CURSOR WITH HOLD FOR
        SELECT CLAIM_ID, CLAIM_AMOUNT, RESERVE_AMOUNT
        FROM CLAIM
        WHERE TENANT_ID  = P_TENANT_ID
          AND BATCH_ID   = P_BATCH_ID
          AND STATUS     = 'APPROVED'
          AND SETTLED_TS IS NULL
        FOR UPDATE OF STATUS, SETTLED_TS;

    DECLARE C_QUEUE SCROLL CURSOR FOR
        SELECT QUEUE_ID, PAYEE_ID
        FROM DISBURSEMENT_QUEUE
        WHERE TENANT_ID = P_TENANT_ID
          AND STATE     = 'READY'
        ORDER BY PRIORITY DESC
        FETCH FIRST 20 ROWS ONLY
        SKIP LOCKED DATA;

    DECLARE C_REPORT CURSOR WITH RETURN TO CLIENT FOR
        SELECT CLAIM_ID, STATUS, SETTLED_TS
        FROM CLAIM
        WHERE TENANT_ID = P_TENANT_ID
          AND BATCH_ID  = P_BATCH_ID
        ORDER BY CLAIM_ID;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET V_DONE = 1;

    DECLARE EXIT HANDLER FOR BATCH_LOCKED
    BEGIN
        SET P_STATUS = 'BATCH_LOCKED';
        SET P_SETTLED_COUNT = 0;
        SET P_DISBURSED_TOTAL = 0;
    END;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE V_STATE CHAR(5);
        DECLARE V_MSG   VARCHAR(200);
        GET DIAGNOSTICS CONDITION 1
            V_STATE = RETURNED_SQLSTATE,
            V_MSG   = MESSAGE_TEXT;
        ROLLBACK TO SAVEPOINT SP_BATCH;
        SET P_STATUS = 'FAILED_' || V_STATE;
        RESIGNAL SQLSTATE '75002' SET MESSAGE_TEXT = V_MSG;
    END;

    SET P_SETTLED_COUNT   = 0;
    SET P_DISBURSED_TOTAL = 0;
    SET P_STATUS          = 'RUNNING';

    SET V_MODE = CLAIMS.G_PROCESSING_MODE;

    SELECT LOCK_STATE
    INTO   V_MODE
    FROM   BATCH_CONTROL
    WHERE  BATCH_ID  = P_BATCH_ID
      AND  TENANT_ID = P_TENANT_ID
    WITH UR;

    IF V_MODE = 'LOCKED' THEN
        SIGNAL BATCH_LOCKED SET MESSAGE_TEXT = 'Batch is locked by another run';
    END IF;

    SAVEPOINT SP_BATCH ON ROLLBACK RETAIN CURSORS;

    UPDATE CLAIM
       SET STATUS = 'SETTLING',
           UPDATED_TS = V_NOW
     WHERE TENANT_ID  = P_TENANT_ID
       AND BATCH_ID   = P_BATCH_ID
       AND STATUS     = 'APPROVED'
       AND SETTLED_TS IS NULL;

    GET DIAGNOSTICS V_ROWS = ROW_COUNT;

    IF V_ROWS = 0 THEN
        SET P_STATUS = 'NOTHING_TO_SETTLE';
        OPEN C_REPORT;
        RETURN;
    ELSEIF V_ROWS > 10000 THEN
        ROLLBACK TO SAVEPOINT SP_BATCH;
        SET P_STATUS = 'BATCH_TOO_LARGE';
        RETURN;
    END IF;

    OUTER_SCAN:
    BEGIN
        FOR row_claim AS C_SCAN CURSOR FOR
            SELECT CLAIM_ID, CLAIM_AMOUNT
            FROM CLAIM
            WHERE TENANT_ID = P_TENANT_ID
              AND BATCH_ID  = P_BATCH_ID
              AND STATUS    = 'SETTLING'
        DO
            SELECT SUM(HOLD_AMOUNT)
            INTO   V_HOLD_TOTAL
            FROM   PAYMENT_HOLD
            WHERE  CLAIM_ID  = row_claim.CLAIM_ID
              AND  ACTIVE_IND = 'Y';

            IF V_HOLD_TOTAL > row_claim.CLAIM_AMOUNT THEN
                SET V_REJECTED = V_REJECTED + 1;
                IF V_REJECTED > 50 THEN
                    LEAVE OUTER_SCAN;
                END IF;
            END IF;
        END FOR;
    END OUTER_SCAN;

    OPEN C_SETTLE;
    SET V_DONE = 0;
    settle_loop:
    WHILE V_DONE = 0 DO
        FETCH C_SETTLE INTO V_CLAIM_ID, V_AMOUNT, V_RESERVE;
        IF V_DONE = 1 THEN
            LEAVE settle_loop;
        END IF;

        SET V_NET = CLAIMS.MONEY(V_AMOUNT - V_RESERVE);

        IF V_NET <= CLAIMS.MONEY(0) THEN
            DELETE FROM CLAIM
             WHERE CURRENT OF C_SETTLE;
            ITERATE settle_loop;
        END IF;

        UPDATE CLAIM
           SET STATUS     = 'SETTLED',
               SETTLED_TS = V_NOW
         WHERE CURRENT OF C_SETTLE;

        BEGIN ATOMIC
            INSERT INTO CLAIM_AUDIT (CLAIM_ID, TENANT_ID, ACTION_CODE, ACTION_TS)
            VALUES (V_CLAIM_ID, P_TENANT_ID, 'SETTLED', V_NOW);

            INSERT INTO SETTLEMENT_LEDGER (CLAIM_ID, TENANT_ID, NET_AMOUNT, POSTED_TS)
            VALUES (V_CLAIM_ID, P_TENANT_ID, V_NET, V_NOW);
        END;

        SET P_SETTLED_COUNT   = P_SETTLED_COUNT + 1;
        SET P_DISBURSED_TOTAL = P_DISBURSED_TOTAL + V_NET;
    END WHILE;
    CLOSE C_SETTLE;

    OPEN C_QUEUE;
    FETCH LAST FROM C_QUEUE INTO V_QUEUE_ID, V_PAYEE_ID;
    IF V_DONE = 0 THEN
        FETCH PRIOR FROM C_QUEUE INTO V_QUEUE_ID, V_PAYEE_ID;
    END IF;
    CLOSE C_QUEUE;

    SELECT DISBURSEMENT_ID
    INTO   V_DISB_ID
    FROM   FINAL TABLE (
        INSERT INTO DISBURSEMENT
            (TENANT_ID, BATCH_ID, PAYEE_ID, AMOUNT, CREATED_TS)
        VALUES (P_TENANT_ID, P_BATCH_ID, V_PAYEE_ID, P_DISBURSED_TOTAL, V_NOW)
    );

    SELECT SUM(CLAIM_AMOUNT)
    INTO   V_STALE_TOTAL
    FROM   CLAIM
    WHERE  TENANT_ID   = P_TENANT_ID
      AND  CREATED_DATE < CURRENT DATE - 90 DAYS
      AND  CLAIM_ID NOT IN (SELECT CLAIM_ID
                              FROM PAYMENT_HOLD
                             WHERE TENANT_ID = P_TENANT_ID);

    SELECT CLAIM_AMOUNT
    INTO   V_PRIOR_AMOUNT
    FROM   CLAIM
    WHERE  TENANT_ID = P_TENANT_ID
      AND  PAYEE_ID  = V_PAYEE_ID
      AND  STATUS    = 'SETTLED';

    IF V_STALE_TOTAL > 100000 THEN
        ROLLBACK TO SAVEPOINT SP_BATCH;
        SET P_STATUS = 'STALE_EXPOSURE_BLOCK';
    ELSEIF V_REJECTED > 0 THEN
        SET P_STATUS = 'SETTLED_WITH_REJECTS';
    ELSE
        SET P_STATUS = 'SETTLED';
    END IF;

    SET V_DISB_ID = NEXT VALUE FOR CLAIMS.DISBURSEMENT_SEQ;

    OPEN C_REPORT;

END P_SETTLE;
